      const boxes = elements.map((element) => element.getBoundingClientRect());
      return boxes.every(
        (box, index) =>
          box.width > 0 &&
          box.height > 0 &&
          box.left >= 0 &&
          box.right <= innerWidth &&
          (!index || box.top >= (boxes[index - 1]?.bottom ?? 0)),
      );
    });
    expect(readable).toBe(true);
    await expectReadableText(page);
